{
  "status": "SUPPORTED",
  "task_summary": "Find fastener and tool, fasten workpiece, return tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The item requiring fastening at the marked location.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly", "part", "object"],
        "required_properties": ["needs_fastening"]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The component used to secure the workpiece.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "rivet"],
        "required_properties": ["compatible_with_workpiece"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastener.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "drill", "wrench", "clamp"],
        "required_properties": ["can_drive_fastener"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the workpiece sits and tool is returned.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "surface"],
        "required_properties": ["supports_objects"]
      }
    ],
    "functional_relations": [
      {
        "id": "compatible_for_fastening",
        "relation": "The fastener must fit the workpiece.",
        "participant_roles": ["fastener", "workpiece"]
      ,
      "required": true
      },
      {
        "id": "applied_to",
        "relation": "The tool applies the fastener to the workpiece.",
        "participant_roles": ["tool", "fastener", "workpiece"]
      ,
      "required": true
      },
      {
        "id": "placed_on",
        "relation": "The tool ends up on the workbench.",
        "participant_roles": ["tool", "workbench"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_components",
        "operation": "Locate the fastener and tool.",
        "participant_roles": ["fastener", "tool"],
        "operation_count": 1
      },
      {
        "id": "complete_fastening",
        "operation": "Secure the workpiece using the tool and fastener.",
        "participant_roles": ["tool", "fastener", "workpiece"],
        "operation_count": 1
      },
      {
        "id": "return_equipment",
        "operation": "Place the tool back on the workbench.",
        "participant_roles": ["tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workpiece": [
        {
          "label": "grey_tray_with_yellow_parts",
          "visual_description": "A grey rectangular tray holding yellow blocks on the table surface."
        }
      ],
      "fastener": [],
      "tool": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "A wooden desk with drawers and legs."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue_cabinet",
        "visual_description": "A tall blue cabinet standing against the wall.",
        "reason": "Closed structure, likely contains tools or fasteners."
      },
      {
        "id": "drawers",
        "label": "drawers",
        "visual_description": "Two blue drawers located under the table.",
        "reason": "Closed structures, likely contain tools or fasteners."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
